:root {
  color-scheme: dark;
  font-family: system-ui, sans-serif;
  font-size: 16px;
  background: #172b3a;
  color: #f6f0df;
  font-synthesis: none;
}

* { box-sizing: border-box; }

body {
  min-width: 360px;
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: #172b3a;
  background-image: radial-gradient(#365263 1px, transparent 1px);
  background-size: 22px 22px;
}

.counter {
  width: min(100%, 520px);
  padding: clamp(24px, 6vw, 42px);
  border: 2px solid #516978;
  border-radius: 8px;
  background: #223a49;
  box-shadow: 8px 8px 0 #0d1d28;
}

.header { text-align: center; }
.eyebrow { color: #f2bd62; font-size: 0.8rem; font-weight: 800; letter-spacing: 0.16em; }
h1 { margin: 10px 0 4px; font-size: clamp(1.7rem, 7vw, 2.3rem); line-height: 1.15; }
.header p { margin: 0; color: #c5d0d1; }

.now-serving {
  margin: 30px 0 22px;
  padding: 20px;
  border: 2px dashed #718895;
  border-radius: 6px;
  background: #172b3a;
  text-align: center;
}
.now-serving h2, .waiting h2 { margin: 0; font-size: 1rem; }
.ticket-number { margin: 4px 0 0; color: #f2bd62; font-size: clamp(4rem, 18vw, 6rem); font-weight: 850; line-height: 1.1; font-variant-numeric: tabular-nums; }

.actions { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.button {
  min-height: 54px;
  padding: 12px 14px;
  border: 2px solid transparent;
  border-radius: 5px;
  font: inherit;
  font-weight: 750;
  cursor: pointer;
  transition: transform 100ms ease, filter 100ms ease, box-shadow 100ms ease;
}
.button-primary { background: #f2bd62; color: #172b3a; box-shadow: 0 4px 0 #bb8432; }
.button-secondary { border-color: #8bb9aa; background: #477c71; color: #fff; box-shadow: 0 4px 0 #315a53; }
.button:hover { filter: brightness(1.08); transform: translateY(-1px); }
.button:active { transform: translateY(3px); box-shadow: none; }
.button:focus-visible { outline: 3px solid #fff; outline-offset: 4px; }

.waiting { margin-top: 32px; }
.waiting-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
.waiting-heading p { margin: 0; color: #c5d0d1; font-variant-numeric: tabular-nums; }
.waiting-heading p span { color: #f2bd62; font-weight: 800; }
.ticket-list { display: flex; flex-wrap: wrap; gap: 9px; min-height: 18px; margin: 14px 0 0; padding: 0; list-style: none; }
.ticket-list li { min-width: 52px; padding: 8px 10px; border: 1px solid #718895; border-radius: 4px; background: #304c5b; text-align: center; font-weight: 750; font-variant-numeric: tabular-nums; }
.empty-message { margin: 14px 0 0; color: #aebdc1; }
.visually-hidden { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }

@media (max-width: 420px) {
  body { padding: 20px 12px; }
  .actions { grid-template-columns: 1fr; }
}

const waiting = [];
let nextNumber = 1;

const currentNumber = document.querySelector('#current-number');
const waitingList = document.querySelector('#waiting-list');
const waitingCount = document.querySelector('#waiting-count');
const emptyMessage = document.querySelector('#empty-message');
const statusMessage = document.querySelector('#status-message');

function render() {
  waitingList.replaceChildren(...waiting.map((number) => {
    const item = document.createElement('li');
    item.textContent = number;
    return item;
  }));
  waitingCount.textContent = waiting.length;
  emptyMessage.hidden = waiting.length > 0;
}

document.querySelector('#take-ticket').addEventListener('click', () => {
  const number = nextNumber++;
  waiting.push(number);
  render();
  statusMessage.textContent = `Ticket ${number} added to the waiting list.`;
});

document.querySelector('#serve-next').addEventListener('click', () => {
  if (waiting.length === 0) {
    statusMessage.textContent = 'No tickets are waiting.';
    return;
  }
  const number = waiting.shift();
  currentNumber.textContent = number;
  render();
  statusMessage.textContent = `Now serving ticket ${number}.`;
});

render();
